// Package fixdata provides types that represent the response from the autofix service.
// FOTIS: Initially copied over from Turboscan, with minor modifications.
// https://github.com/github/codeql-core/issues/4785#issuecomment-2640460813 for reference.
package fixdata

import (
	"github.com/github/codeml-autofix/go/v3/pkg/autofix"
	"github.com/github/codeml-autofix/go/v3/pkg/autofix/alerts"
	"github.com/github/codeml-autofix/go/v3/pkg/autofix/codebase"
)

// AutofixResponse is a collection of Output values produced for processed alerts.
type AutofixResponse []Output

// NewAutofixOutput constructs an Output describing the result of processing an alert.
func NewAutofixOutput(version, model string, alert *alerts.Alert, outcome Outcome) Output {
	// Reconstruct the SARIF message: newline-join the messages of each variant.
	var message string
	for i, variant := range alert.Variants {
		if i > 0 {
			message += "\n"
		}
		message += variant.Message
	}

	// Create the alert representation
	alertResp := RespAlert{
		ID:       alert.ID,
		Message:  message,
		RuleID:   alert.GetRule().ID,
		Location: FromSourceLocation(alert.Location),
	}

	return Output{
		AutofixVersion: version,
		Model:          model,
		Alert:          alertResp,
		Outcome:        outcome,
	}
}

// Output is the outcome of trying to fix an alert (either a proposed fix, or an error),
// in a format suitable for JSON serialization.
type Output struct {
	AutofixVersion string    `json:"autofixVersion"`
	Model          string    `json:"model,omitempty"` // The model used to generate the fix.
	Alert          RespAlert `json:"alert,omitempty"`
	Outcome        Outcome   `json:"outcome"`
}

// RespAlert is a serializable representation of an alert embedded in a fix response.
type RespAlert struct {
	// ID is the alerts unique identifier. This is only set when the library's
	// client provides an alert ID. When the alert is created by converting a
	// SARIF, this is set to the result GUID.
	ID       string   `json:"id"`
	Message  string   `json:"message"`
	RuleID   string   `json:"ruleId"`
	Location Location `json:"location"`
}

// OutcomeKind identifies whether an Outcome is a fix or an error.
type OutcomeKind string

// OutcomeKind values identify whether an Outcome is a fix or an error.
const (
	OutcomeKindFix   OutcomeKind = "fix"
	OutcomeKindError OutcomeKind = "error"
)

// Outcome is a proposed fix for an alert (as opposed to an error), in a format suitable
// for JSON serialization.
type Outcome struct {
	// kind: fix|error
	Kind OutcomeKind `json:"kind"`
	// The edits comprising the fix
	Diffs      []Diff                `json:"diffs,omitempty"`
	Assessment Assessment            `json:"assessment,omitempty"`
	Details    Details               `json:"details,omitempty"`
	Severity   autofix.ErrorSeverity `json:"severity,omitempty"` // The severity of the fix, e.g. "low", "high", "critical".

	// AutofixError is the structured autofix error. This is not serialized to JSON.
	AutofixError autofix.AutofixError

	// The error message, if `kind` is 'error'.
	Error string `json:"error,omitempty"`
	// Whether the error is transient, if `kind` is 'error'.
	Transient bool `json:"transient,omitempty"`

	// The transcript of the conversation with the model.
	// This will be nil if the fix was not generated by a model.
	Transcript *string `json:"transcript,omitempty"`
}

// NewErrorOutcome constructs an error Outcome based on the provided autofix error.
func NewErrorOutcome(err autofix.AutofixError, transcript *string) Outcome {
	// Handle the error case
	return Outcome{ //nolint:exhaustruct // We don't need all properties
		Kind:         OutcomeKindError,
		AutofixError: err,
		Error:        err.Error(),
		Transient:    err.Retryable(),
		Severity:     err.ErrorSeverity(),
		Transcript:   transcript,
	}
}

// Diff represents the textual diff of proposed changes to a file.
type Diff struct {
	Path string `json:"path,omitempty"`
	Diff string `json:"diff"`
}

// Rule identifies the CodeQL rule (or analogous rule) involved in the alert/fix.
type Rule struct {
	ID string `json:"id"`
}

// Location specifies a source location for an alert.
type Location struct {
	Path        string `json:"path"`
	StartLine   int    `json:"startLine"`
	StartColumn int    `json:"startColumn"`
	EndLine     int    `json:"endLine"`
	EndColumn   int    `json:"endColumn"`
}

// FromSourceLocation converts an internal SourceLocation to a serializable Location.
func FromSourceLocation(loc codebase.SourceLocation) Location {
	return Location{
		Path:        loc.File.Path,
		StartLine:   int(loc.StartLine()),
		StartColumn: int(loc.StartColumn()),
		EndLine:     int(loc.EndLine()),
		EndColumn:   int(loc.EndColumn()),
	}
}

// AssessmentOutcome indicates whether an assessment judged a fix valid.
type AssessmentOutcome string

// AssessmentOutcome values identify whether an assessment judged a fix valid.
const (
	AssessmentOutcomeValid   AssessmentOutcome = "valid"
	AssessmentOutcomeInvalid AssessmentOutcome = "invalid"
)

// Assessment is the outcome of checking whether a fix suggestion is valid.
//
// For invalid fixes, `problems` is a list of potential reasons why the fix is
// invalid.
//
// Iff outcome is 'valid', `problems` is an empty list.
type Assessment struct {
	Outcome  AssessmentOutcome `json:"outcome,omitempty"`
	Problems []Problem         `json:"problems,omitempty"`
}

// ProblemKind categorizes validation problems encountered when assessing a fix.
type ProblemKind string

// ProblemKind values categorize validation issues encountered when assessing a fix.
const (
	ProblemKindNoCodeChanges        ProblemKind = "no code changes"
	ProblemKindSyntaxError          ProblemKind = "syntax error"
	ProblemKindSemanticError        ProblemKind = "semantic error"
	ProblemKindMissingDependency    ProblemKind = "missing dependency"
	ProblemKindVulnerableDependency ProblemKind = "vulnerable dependency"
)

// Problem describes a specific issue found during assessment.
type Problem struct {
	Kind        ProblemKind `json:"kind"`
	Description string      `json:"description"`
}

// Details contains additional descriptive information about a fix.
type Details struct {
	// A natural-language description of the fix.
	FixDescription string `json:"fixDescription,omitempty"`
	// Information about any dependencies added by the fix.
	DependencyMetadata []DependencyMetadata `json:"dependencyMetadata,omitempty"`
}

// DependencyMetadata holds metadata for a dependency introduced by a fix.
type DependencyMetadata struct {
	Name        string     `json:"name"`
	Version     string     `json:"version"`
	Ecosystem   string     `json:"ecosystem"`
	Description string     `json:"description,omitempty"`
	URL         string     `json:"url,omitempty"`
	IsMalicious bool       `json:"isMalicious,omitempty"`
	Advisories  []Advisory `json:"advisories,omitempty"`
}

// Advisory summarizes a security advisory associated with a dependency.
type Advisory struct {
	// The advisory's ID.
	ID string `json:"ghsa_id"`
	// The URL of the advisory on GitHub.
	HTMLURL string `json:"html_url"`
	// A brief description of the advisory.
	Summary string `json:"summary"`
	// A longer description of the advisory, if	available.
	Description string `json:"description,omitempty"`
	// The severity of the advisory.
	Severity string `json:"severity"`
}
